CREATE TABLE library_books (id text PRIMARY KEY, school_id text NOT NULL REFERENCES tenants(id), isbn text, title text NOT NULL, copies int NOT NULL CHECK (copies > 0), available int NOT NULL CHECK (available >= 0), replacement_cents bigint NOT NULL DEFAULT 0);
CREATE TABLE library_issues (id text PRIMARY KEY, school_id text NOT NULL REFERENCES tenants(id), book_id text NOT NULL REFERENCES library_books(id), student_id text NOT NULL REFERENCES students(id), issued_by text NOT NULL REFERENCES users(id), issued_at timestamptz NOT NULL DEFAULT now(), due_at timestamptz NOT NULL, returned_at timestamptz, charged boolean NOT NULL DEFAULT false);
CREATE TABLE inventory_items (id text PRIMARY KEY, school_id text NOT NULL REFERENCES tenants(id), name text NOT NULL, category text NOT NULL, unit text NOT NULL, quantity bigint NOT NULL DEFAULT 0, reorder_level bigint NOT NULL DEFAULT 0);
CREATE TABLE inventory_transactions (id text PRIMARY KEY, school_id text NOT NULL REFERENCES tenants(id), item_id text NOT NULL REFERENCES inventory_items(id), actor_id text NOT NULL REFERENCES users(id), type text NOT NULL CHECK (type IN ('receive','issue')), quantity bigint NOT NULL CHECK (quantity > 0), reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
